<template><Teleport to="body"><view v-if="drag" class="notebook-drag-layer" aria-live="polite"><view :class="['notebook-drop-target',{ready:drag.ready,accepted:drag.phase==='accepted'}]" :style="{left:drag.targetX+'px',top:drag.targetY+'px'}"><Icon :name="drag.notebook==='known'?'repeat':'check'"/><Bi :zh="drag.notebook==='known'?(drag.ready?'松手放回复习':'向上拖回复习'):(drag.ready?'松手加入已会':'向上拖入已会')" :fr="drag.notebook==='known'?(drag.ready?'Relâcher pour réviser':'Glisser vers Révision'):(drag.ready?'Relâcher pour acquérir':'Glisser vers Acquis')" small/></view><view :class="['notebook-drag-ghost',drag.phase]" :style="{width:width+'px',transform:'translate3d('+(drag.x-width/2)+'px,'+(drag.y-36)+'px,0)'}"><view class="notebook-drag-card"><text lang="fr">{{ drag.label }}</text><Icon name="book"/></view></view></view></Teleport></template>
<script setup>import {computed} from 'vue';import Bi from './Bi.vue';import Icon from './Icon.vue';const props=defineProps({drag:Object});const width=computed(()=>Math.min(260,Math.max(160,props.drag?.rect?.width||220)));</script>
<style scoped>.notebook-drag-layer{position:fixed;inset:0;pointer-events:none;z-index:215}.notebook-drop-target{position:absolute;display:flex;align-items:center;justify-content:center;gap:10px;width:190px;min-height:63px;padding:10px 15px;transform:translate(-50%,-50%) scale(.94);border:1px dashed var(--accent);border-radius:23px;background:var(--theme-panel,#f8faff);color:var(--accent-dark);box-shadow:0 7px 25px rgba(var(--theme-rgb),.09);opacity:.82;transition:transform .24s cubic-bezier(.2,.8,.3,1.15),opacity .2s,box-shadow .2s}.notebook-drop-target.ready{transform:translate(-50%,-50%) scale(1.04);opacity:1;border-style:solid;background:var(--theme-soft,#e7eefb);box-shadow:0 0 0 8px rgba(var(--theme-rgb),.07),0 9px 28px rgba(var(--theme-rgb),.16)}.notebook-drop-target.accepted{opacity:0;transform:translate(-50%,-50%) scale(1.12)}.notebook-drop-target>.icon{width:22px;height:22px}.notebook-drop-target :deep(.bi-fr){font-size:9px}.notebook-drag-ghost{position:absolute;left:0;top:0;will-change:transform;opacity:1}.notebook-drag-card{display:flex;align-items:center;gap:12px;min-height:72px;padding:15px 18px;border-radius:19px;background:var(--theme-panel,#f8faff);border:1px solid #ffffffdd;box-shadow:0 12px 35px rgba(var(--theme-rgb),.22),0 2px 8px #3240570d;transform:scale(1.035);animation:notebook-lift .18s ease-out}.notebook-drag-card>text{flex:1;font:20px/1.5 Georgia,serif;color:var(--ink);overflow-wrap:anywhere}.notebook-drag-card>.icon{width:18px;height:18px;color:var(--accent)}.notebook-drag-ghost.accepted,.notebook-drag-ghost.returning{transition:transform .24s cubic-bezier(.2,.8,.3,1),opacity .24s}.notebook-drag-ghost.accepted{opacity:0}.notebook-drag-ghost.accepted .notebook-drag-card{transform:scale(.8);transition:transform .24s}.notebook-drag-ghost.returning{opacity:0}.notebook-drag-ghost.returning .notebook-drag-card{transform:scale(.97);transition:transform .24s}@keyframes notebook-lift{from{opacity:.5;transform:scale(.98)}to{opacity:1;transform:scale(1.035)}}@media(prefers-reduced-motion:reduce){.notebook-drop-target,.notebook-drag-ghost,.notebook-drag-card{animation:none!important;transition:none!important}}</style>

<style scoped>.notebook-drop-target:not(.ready):not(.accepted){animation:notebook-target-pulse 1.2s ease-in-out infinite}@keyframes notebook-target-pulse{0%,100%{opacity:.65;box-shadow:0 0 0 0 rgba(var(--theme-rgb),.04)}50%{opacity:1;box-shadow:0 0 0 9px rgba(var(--theme-rgb),.14)}}@media(prefers-reduced-motion:reduce){.notebook-drop-target{animation:none!important}}</style>
